honest:
def center_text_block(lines, width):
    result = []
    for line in lines:
        pad = width - len(line)
        if pad <= 0:
            result.append(line)
        else:
            left = pad // 2
            result.append(' ' * left + line + ' ' * (pad - left))
    return result

